import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import {createApplication} from '../src/server.js';import {bootstrapAdmin} from '../src/start.js';
test('hosting bootstrap requires a secret for first admin, never rotates existing credentials',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'gdqpan-bootstrap-'));const app=createApplication({data:dir,local:true});try{await assert.rejects(bootstrapAdmin(app,'qa-admin@example.test','short'),/ADMIN_BOOTSTRAP_PASSWORD/);assert.equal(app.db.prepare('SELECT COUNT(*) AS n FROM users').get().n,0);await bootstrapAdmin(app,'qa-admin@example.test','QA-bootstrap-only-123');const original=app.db.prepare('SELECT * FROM users').get();assert.equal(original.role,'admin');assert.equal(original.approval,'approved');await bootstrapAdmin(app,'other@example.test','QA-other-only-456');assert.equal(app.db.prepare('SELECT password FROM users').get().password,original.password);assert.equal(app.db.prepare('SELECT COUNT(*) AS n FROM users').get().n,1);}finally{app.close();fs.rmSync(dir,{recursive:true,force:true});}});
